import React, { useState } from "react";
import { graphql, type HeadFC } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";
import Layout from "../components/Layout";
import SEO from "../components/seo";

const ContactPage: React.FC = () => {
  const { t } = useTranslation("contact");
  const [form, setForm] = useState({ name: "", email: "", company: "", message: "", budget: "" });
  const [status, setStatus] = useState<"idle" | "sending" | "success" | "error">("idle");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus("sending");
    try {
      await addDoc(collection(db, "contactRequests"), {
        ...form,
        createdAt: serverTimestamp(),
      });
      setStatus("success");
      setForm({ name: "", email: "", company: "", message: "", budget: "" });
    } catch {
      setStatus("error");
    }
  };

  const inputStyle: React.CSSProperties = {
    width: "100%", padding: "12px 16px",
    background: "var(--bg-card)", border: "1px solid var(--border-1)",
    borderRadius: "var(--radius-md)", color: "var(--text-1)",
    fontFamily: "'DM Sans',sans-serif", fontSize: 15,
    outline: "none", transition: "border-color 0.15s ease",
  };

  return (
    <Layout>
      <div style={{ paddingTop: "var(--space-10)", paddingBottom: "var(--space-10)" }}>
        <div className="cc-container" style={{ paddingTop: "var(--space-8)" }}>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
            {/* Left */}
            <div>
              <div className="section-label">
                <span className="num">00</span>
                <span className="rule" />
                <span className="name">{t("sectionName")}</span>
              </div>
              <h1 className="text-h1">{t("title")}</h1>
              <p className="text-lg-body mt-4">{t("sub")}</p>

              <div className="flex flex-col gap-6 mt-10">
                {(t("promises", { returnObjects: true }) as Array<{ title: string; text: string }>).map((p) => (
                  <div key={p.title} className="flex gap-4">
                    <div style={{
                      width: 36, height: 36, background: "var(--blue-dim)", border: "1px solid var(--border-2)",
                      borderRadius: "var(--radius-sm)", display: "flex", alignItems: "center",
                      justifyContent: "center", flexShrink: 0, color: "var(--blue)",
                    }}>
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M20 6L9 17l-5-5" /></svg>
                    </div>
                    <div>
                      <p style={{ fontFamily: "'Sora',sans-serif", fontSize: 16, fontWeight: 600, color: "var(--text-1)" }}>{p.title}</p>
                      <p className="text-base-body mt-1">{p.text}</p>
                    </div>
                  </div>
                ))}
              </div>

              <div style={{ marginTop: "var(--space-8)", padding: "var(--space-5)", background: "var(--bg-surface)", border: "1px solid var(--border-1)", borderRadius: "var(--radius-md)" }}>
                <p className="text-sm-body">{t("email")}</p>
                <a href="mailto:hello@codecrafted.ca" style={{ fontFamily: "'Sora',sans-serif", fontSize: 18, fontWeight: 600, color: "var(--text-1)", marginTop: 4, display: "block" }}>
                  hello@codecrafted.ca
                </a>
              </div>
            </div>

            {/* Form */}
            <div className="cc-card">
              {status === "success" ? (
                <div style={{ textAlign: "center", padding: "var(--space-8)" }}>
                  <div style={{ fontSize: 48 }}>✓</div>
                  <h2 className="text-h2 mt-4">{t("successTitle")}</h2>
                  <p className="text-base-body mt-3">{t("successSub")}</p>
                </div>
              ) : (
                <form onSubmit={(e) => void handleSubmit(e)} className="flex flex-col gap-5">
                  <h2 className="text-h3">{t("formTitle")}</h2>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 11, letterSpacing: "0.08em", color: "var(--text-3)", textTransform: "uppercase", display: "block", marginBottom: 8 }}>{t("fieldName")}</label>
                      <input name="name" value={form.name} onChange={handleChange} required placeholder={t("fieldNamePlaceholder")} style={inputStyle} />
                    </div>
                    <div>
                      <label style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 11, letterSpacing: "0.08em", color: "var(--text-3)", textTransform: "uppercase", display: "block", marginBottom: 8 }}>{t("fieldEmail")}</label>
                      <input name="email" type="email" value={form.email} onChange={handleChange} required placeholder={t("fieldEmailPlaceholder")} style={inputStyle} />
                    </div>
                  </div>

                  <div>
                    <label style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 11, letterSpacing: "0.08em", color: "var(--text-3)", textTransform: "uppercase", display: "block", marginBottom: 8 }}>{t("fieldCompany")}</label>
                    <input name="company" value={form.company} onChange={handleChange} placeholder={t("fieldCompanyPlaceholder")} style={inputStyle} />
                  </div>

                  <div>
                    <label style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 11, letterSpacing: "0.08em", color: "var(--text-3)", textTransform: "uppercase", display: "block", marginBottom: 8 }}>{t("fieldBudget")}</label>
                    <select name="budget" value={form.budget} onChange={handleChange} style={{ ...inputStyle, cursor: "pointer" }}>
                      <option value="">{t("fieldBudgetDefault")}</option>
                      {(t("budgetOptions", { returnObjects: true }) as string[]).map((opt) => (
                        <option key={opt} value={opt}>{opt}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 11, letterSpacing: "0.08em", color: "var(--text-3)", textTransform: "uppercase", display: "block", marginBottom: 8 }}>{t("fieldMessage")}</label>
                    <textarea name="message" value={form.message} onChange={handleChange} required rows={5} placeholder={t("fieldMessagePlaceholder")} style={{ ...inputStyle, resize: "vertical" }} />
                  </div>

                  {status === "error" && (
                    <p style={{ color: "#EF4444", fontFamily: "'DM Sans',sans-serif", fontSize: 14 }}>{t("errorMsg")}</p>
                  )}

                  <button type="submit" disabled={status === "sending"} className="btn-primary" style={{ justifyContent: "center" }}>
                    {status === "sending" ? t("sending") : t("submit")}
                    {status !== "sending" && (
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
                    )}
                  </button>

                  <p style={{ fontFamily: "'DM Sans',sans-serif", fontSize: 12, color: "var(--text-3)", textAlign: "center" }}>{t("privacyNote")}</p>
                </form>
              )}
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default ContactPage;

export const Head: HeadFC = ({ data, location }: any) => (
  <SEO
    data={data.allDataJson.nodes[0]}
    title="Contact - Code Crafted"
    description="Book a free 30-minute discovery call. No pitch. No commitment. A genuine conversation about whether custom software is right for your business."
    language={data.locales?.edges?.[0]?.node?.language}
    originalPath={location.pathname}
    pageSchemaType="ContactPage"
    schemaType="LocalBusiness"
    includeLocalBusinessDetails
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges { node { ns data language } }
    }
    allDataJson {
      nodes {
        companyName address city province country postalCode
        phone email instagram facebook linkedin whatsapp url
        founder { name jobTitle sameAs }
      }
    }
  }
`;
